// AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0
std::vector<pid_t> processes_using_file( const std::string & file )
{
    std::vector<pid_t> pids;

    struct stat target;

    if( ::stat( file.c_str(), &target ) != 0 ) {
        return pids;    // file does not exist (yet) -> nobody can hold it
    }

    DIR * proc = ::opendir( "/proc" );

    if( !proc ) {
        DEBUG( Tools::format( "cannot read /proc: %s", std::strerror( errno ) ) );
        return pids;
    }

    const pid_t self = ::getpid();

    while( struct dirent * entry = ::readdir( proc ) ) {
        if( !is_number( entry->d_name ) ) {
            continue;
        }

        const pid_t pid = (pid_t)std::atoi( entry->d_name );

        if( pid == self ) {
            continue;
        }

        if( has_file_open( "/proc/" + std::string( entry->d_name ) + "/fd", target ) ) {
            pids.push_back( pid );
        }
    }

    ::closedir( proc );

    return pids;
}
