FileState file_state( const std::string & file )
{
    FileState state;
    struct stat st;

    if( ::stat( file.c_str(), &st ) != 0 ) {
        return state;
    }

    state.valid      = true;
    state.dev        = st.st_dev;
    state.ino        = st.st_ino;
    state.size       = st.st_size;
    state.mtime      = st.st_mtime;
    state.mtime_nsec = (long)st.st_mtim.tv_nsec;

    return state;
}
