// AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0
bool file_was_modified( const FileState & before, const FileState & after )
{
    if( !before.valid || !after.valid ) {
        return false;   // vanished: cannot tell, the reader saw what it saw
    }

    if( !before.sameFile( after ) ) {
        return false;   // replaced (rename): the read was a consistent snapshot
    }

    if( after.size < before.size ) {
        return true;    // truncated
    }

    // appended to or rewritten in place - stat cannot tell them apart, so any
    // mtime change counts as a modification
    return after.mtime != before.mtime || after.mtime_nsec != before.mtime_nsec;
}
