// AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0
bool FileLock::tryLock( const std::string & path )
{
    unlock();

    m_path = path;

    m_fd = ::open( path.c_str(), O_RDWR | O_CREAT | O_CLOEXEC, 0666 );

    if( m_fd < 0 ) {
        m_error = "cannot open lock file '" + path + "': " + std::strerror( errno );
        return false;
    }

    if( ::flock( m_fd, LOCK_EX | LOCK_NB ) != 0 ) {
        m_error = "lock file '" + path + "' is locked by another process";
        ::close( m_fd );
        m_fd = -1;
        return false;
    }

    m_error.clear();
    return true;
}
