// AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0
void FileLock::unlock()
{
    if( m_fd >= 0 ) {
        ::flock( m_fd, LOCK_UN );
        ::close( m_fd );
        m_fd = -1;
    }
}
